  ('anillo-vibrador-bala-recargable', NULL, 'Anillo Vibrador con Bala Recargable', 'juguetes-anillos', 0, '/products/anillo-vibrador-bala-recargable.png', '["Nuevo"]', '{}', 'Un anillo de silicona suave con una bala vibradora extraíble que potencia el placer de los dos. Resistente al agua, libre de ftalatos y con 7 ritmos de vibración diferentes para ir variando la intensidad.', 'Colocá el anillo en la base y ajustá la bala vibradora a tu gusto. Usalo con lubricante a base de agua. Es resistente al agua pero no sumergible: limpialo con un paño húmedo después de cada uso. Se recarga por USB.', NULL, 0, 'NONE', 0, '#DC015B', '#A80044', 0, 1, 0);
INSERT IGNORE INTO products (slug, sku, nombre, categoria, precio, imagen, insignias, variantes, descripcion, instrucciones, promo, descuento_porcentaje, tipo_promocion, descuento_segunda_unidad, tinte_inicio, tinte_fin, destacado, activo, sin_stock) VALUES
  ('bomba-vacio-pene', NULL, 'Bomba de Vacío para Pene', 'juguetes-bombas-vacio', 0, '/products/bomba-vacio-pene.png', '["Nuevo"]', '{}', 'Un sistema completo de bomba de vacío para pene, con cilindro graduado, válvula de liberación rápida y manguera con pera manual. Ayuda a lograr una erección más firme por estimulación de la circulación.', 'Aplicá un poco de lubricante en la base para mejorar el sello. Bombeá de a poco hasta sentir una succión cómoda, nunca forzada, y liberá la válvula para soltar la presión. Usalo por sesiones cortas y limpiá cada pieza con agua y jabón neutro después de cada uso.', NULL, 0, 'NONE', 0, '#DC015B', '#A80044', 0, 1, 0);
INSERT IGNORE INTO products (slug, sku, nombre, categoria, precio, imagen, insignias, variantes, descripcion, instrucciones, promo, descuento_porcentaje, tipo_promocion, descuento_segunda_unidad, tinte_inicio, tinte_fin, destacado, activo, sin_stock) VALUES
  ('kit-estimuladores-intercambiables', NULL, 'Kit de Estimuladores Intercambiables', 'juguetes-estimuladores', 0, '/products/kit-estimuladores-intercambiables.png', '["Nuevo"]', '{}', 'Un set de 5 cabezales de silicona con texturas y formas distintas más un bullet vibrador, para combinar y probar qué estimulación gusta más.', 'Encajá el cabezal elegido en el bullet vibrador y activalo con el botón. Usalo con lubricante a base de agua y limpiá cada pieza por separado después de cada sesión.', NULL, 0, 'NONE', 0, '#DC015B', '#A80044', 0, 1, 0);
