  ('anillo-vibrador-prostata', NULL, 'Anillo Vibrador para Próstata', 'juguetes-anillos', 0, '/products/anillo-vibrador-prostata.png', '["Nuevo"]', '{}', 'Un estimulador de próstata de silicona negra con anillo integrado para la base del pene y motor vibrador tipo bala. Mide 13 x 7,4 x 2,3 cm y pesa 101 g (medidas impresas en la caja). De la línea Maxthor.', 'Cargá el motor antes del primer uso. Usalo con lubricante a base de agua: colocá el anillo en la base del pene (cómodo, nunca ajustado al punto de doler) e introducí la parte de próstata de a poco. Si sentís dolor o mucha molestia, quitalo de inmediato. Limpialo con agua y jabón neutro después de cada uso.', NULL, 0, 'NONE', 0, '#DC015B', '#A80044', 0, 1, 0);
INSERT IGNORE INTO products (slug, sku, nombre, categoria, precio, imagen, insignias, variantes, descripcion, instrucciones, promo, descuento_porcentaje, tipo_promocion, descuento_segunda_unidad, tinte_inicio, tinte_fin, destacado, activo, sin_stock) VALUES
  ('masturbador-bolsillo-mitta', NULL, 'Masturbador de Bolsillo Mitta', 'juguetes-masturbadores', 0, '/products/masturbador-bolsillo-mitta.png', '["Nuevo"]', '{}', 'Un masturbador de bolsillo realista ("pocket pussy"), con apertura texturada. De la línea "Mitta — Tight & Wet Pocket Pussy".', 'Aplicá lubricante a base de agua dentro y en la entrada. Lavalo con agua tibia y jabón neutro después de cada uso y dejalo secar bien al aire antes de guardarlo.', NULL, 0, 'NONE', 0, '#DC015B', '#A80044', 0, 1, 0);
INSERT IGNORE INTO products (slug, sku, nombre, categoria, precio, imagen, insignias, variantes, descripcion, instrucciones, promo, descuento_porcentaje, tipo_promocion, descuento_segunda_unidad, tinte_inicio, tinte_fin, destacado, activo, sin_stock) VALUES
  ('vibrador-anal', NULL, 'Vibrador Anal', 'juguetes-anal-toys', 0, '/products/vibrador-anal.png', '["Nuevo"]', '{}', 'Un plug/vibrador anal negro controlable por aplicación de celular, con 9 modos de vibración seleccionables desde el teléfono. De la línea Noctis.', 'Cargalo por completo antes del primer uso y descargá la app indicada por el fabricante (se vincula por Bluetooth). Usalo siempre con abundante lubricante a base de agua, introducilo de a poco dejando la base fuera del cuerpo, y manejá los modos desde el botón del equipo o la app. Limpialo con agua y jabón neutro después de cada uso.', NULL, 0, 'NONE', 0, '#DC015B', '#A80044', 0, 1, 0);
INSERT IGNORE INTO products (slug, sku, nombre, categoria, precio, imagen, insignias, variantes, descripcion, instrucciones, promo, descuento_porcentaje, tipo_promocion, descuento_segunda_unidad, tinte_inicio, tinte_fin, destacado, activo, sin_stock) VALUES
  ('vibrador-huevo-duoluxe', NULL, 'Vibrador Huevo DuoLuxe', 'juguetes-vibradores', 0, '/products/vibrador-huevo-duoluxe.png', '["Nuevo"]', '{}', 'Un vibrador en forma de "U" para usar en pareja durante la penetración (un extremo estimula el punto G, el otro el clítoris). Con 10 modos de vibración, control por app vía Bluetooth, hasta 1,4 h de uso continuo, carga magnética USB (2 h) y resistencia al agua IP65. De la línea DuoLuxe.', 'Cargalo por completo antes del primer uso (2 h de carga) y descargá la app indicada por el fabricante. Usalo con abundante lubricante a base de agua, colocándolo con un extremo sobre el punto G y el otro sobre el clítoris. Lavalo con agua después de cada uso, secalo bien y guardalo en un lugar limpio.', NULL, 0, 'NONE', 0, '#DC015B', '#A80044', 0, 1, 0);
INSERT IGNORE INTO products (slug, sku, nombre, categoria, precio, imagen, insignias, variantes, descripcion, instrucciones, promo, descuento_porcentaje, tipo_promocion, descuento_segunda_unidad, tinte_inicio, tinte_fin, destacado, activo, sin_stock) VALUES
  ('vibrador-silkyvibe', NULL, 'Vibrador SilkyVibe', 'juguetes-vibradores', 0, '/products/vibrador-silkyvibe.png', '["Nuevo"]', '{}', 'Un vibrador curvo color violeta, de tacto suave, con control remoto inalámbrico independiente. Carga magnética USB (1,5 h) y autonomía de hasta 2 h.', 'Cargá tanto el vibrador como el control remoto antes del primer uso (1,5 h). Usalo con lubricante a base de agua y manejá la intensidad desde el control remoto. Lavalo con agua y jabón neutro después de cada uso y guardalo junto con el control en un lugar limpio.', NULL, 0, 'NONE', 0, '#DC015B', '#A80044', 0, 1, 0);
INSERT IGNORE INTO products (slug, sku, nombre, categoria, precio, imagen, insignias, variantes, descripcion, instrucciones, promo, descuento_porcentaje, tipo_promocion, descuento_segunda_unidad, tinte_inicio, tinte_fin, destacado, activo, sin_stock) VALUES
  ('set-anillos-drakon', NULL, 'Set de anillos Drakon', 'juguetes-anillos', 0, '/products/set-anillos-drakon.png', '["Nuevo"]', '{}', 'Anillo peneano de silicona negra texturada, con diseño decorativo tipo "alas". Una de las piezas del set mide 25 mm de diámetro interno x 47 mm de alto, peso 4,5 g (puede haber más de un tamaño en el set).', 'Lavalo antes del primer uso. Colocalo en la base del pene antes de la erección completa, estirando la silicona con cuidado. Tiene que quedar firme pero cómodo. No usar por más de 20-30 minutos seguidos. Lavalo y guardalo limpio después de cada uso.', NULL, 0, 'NONE', 0, '#DC015B', '#A80044', 0, 1, 0);
